#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

class Solution {
    int best;

    void update(int cost, int target) {
        if (abs(cost - target) < abs(best - target)) {
            best = cost;
        } else if (abs(cost - target) == abs(best - target) && cost < best) {
            best = cost;
        }
    }

    void dfs(int idx, int curr, const vector<int>& toppingCosts, int target) {
        update(curr, target);
        if (curr >= target || idx == toppingCosts.size()) return;
        int top = toppingCosts[idx];
        dfs(idx + 1, curr, toppingCosts, target);
        dfs(idx + 1, curr + top, toppingCosts, target);
        dfs(idx + 1, curr + 2 * top, toppingCosts, target);
    }

public:
    int closestCost(vector<int>& baseCosts, vector<int>& toppingCosts, int target) {
        best = baseCosts[0];
        for (int b : baseCosts) {
            dfs(0, b, toppingCosts, target);
        }
        return best;
    }
};

class Solution {
    private int best;

    private void update(int cost, int target) {
        if (Math.abs(cost - target) < Math.abs(best - target)) {
            best = cost;
        } else if (Math.abs(cost - target) == Math.abs(best - target) && cost < best) {
            best = cost;
        }
    }

    private void dfs(int idx, int curr, int[] toppingCosts, int target) {
        update(curr, target);
        if (curr >= target || idx == toppingCosts.length) return;
        int top = toppingCosts[idx];
        dfs(idx + 1, curr, toppingCosts, target);
        dfs(idx + 1, curr + top, toppingCosts, target);
        dfs(idx + 1, curr + 2 * top, toppingCosts, target);
    }

    public int closestCost(int[] baseCosts, int[] toppingCosts, int target) {
        best = baseCosts[0];
        for (int b : baseCosts) {
            dfs(0, b, toppingCosts, target);
        }
        return best;
    }
}

