var closestCost = function(baseCosts, toppingCosts, target) {
    let best = baseCosts[0];

    const update = (cost) => {
        if (Math.abs(cost - target) < Math.abs(best - target)) {
            best = cost;
        } else if (Math.abs(cost - target) === Math.abs(best - target) && cost < best) {
            best = cost;
        }
    };

    const dfs = (idx, curr) => {
        update(curr);
        if (curr >= target || idx === toppingCosts.length) return;
        const top = toppingCosts[idx];
        dfs(idx + 1, curr);
        dfs(idx + 1, curr + top);
        dfs(idx + 1, curr + 2 * top);
    };

    for (const b of baseCosts) {
        dfs(0, b);
    }
    return best;
};
